def generateEnemyTable(world: "GrimDawnWorld"):
    #We are just shuffling the list of non-boss enemies, no attempt at balancing is being made.
    #We need a list of enemies equal in length to enemyListNonBoss
    #TODO Implement the logic to allow bosses to be shuffled as well.

    #First, copy either the full list or the dangerous list
    if world.options.dangerous_enemies == True:
        enemyCurated = set(enemyDangerous)
    else:
        enemyCurated = set(enemyListNonBoss)

    #Second, determine if the dlc is enabled and create a remove enemies list with only enemies that are unique to the dlc if it's disabled
    if world.options.dlc_aom == False:
        #Since there are duplicate enemies entries in base game and AoM (since they are just edited),
        #  we only want to remove enemies that are unique to the dlc. So first we difference the sets
        #  of AoM and base game to remove duplicates, then difference the curated list with that result.
        enemyCurated.difference_update(set(enemyListAoM))
        #enemyCurated.difference_update(set(enemyListFG)) #aom is required for fg
    if world.options.dlc_fg == False:
        enemyCurated.difference_update(set(enemyListFG))

    #Third, convert to a sorted list, fill spillover, and world shuffle
    enemyCuratedList = sorted(enemyCurated)
    list_size_multiplier = len(enemyListNonBoss) // len(enemyCuratedList)
    enemyReturnList = enemyCuratedList * list_size_multiplier
    #Fill spillover count
    spillover = len(enemyListNonBoss) - len(enemyReturnList)
    enemyReturnList += enemyCuratedList[:spillover]

    #Once the curated list of enemies is finally obtained, shuffle it.
    world.random.shuffle(enemyReturnList)
    return enemyReturnList